INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人助けが大好き！　前向き格闘娘", 100101, "東山奈央", 2, "獣人族", 44, 27, "ヒヨリ", "人助け、応援", 8, 0, "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "トゥインクルウィッシュ", 155, 16);
