INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("クールで何事にも真っ直ぐな剣士", 100301, "早見沙織", 2, "魔族", 46, 12, "レイ", "読書、乗馬、お茶", 1, 0, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "トゥインクルウィッシュ", 163, 18);
