INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒーローに憧れる騎士見習いの少女", 100501, "下田麻美", 8, "獣人族", 40, 25, "マツリ", "ヒーローごっこ", 11, 0, "O", "？？？", "王宮騎士団（NIGHTMARE）", 146, 12);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("甘え上手なみんなの人気者", 100601, "浅倉杏美", 7, "魔族", 42, 22, "アカリ", "サックス", 11, 0, "O", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "悪魔偽王国軍（ディアボロス）", 150, 13);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("プリン大好きゴースト娘", 100701, "雨宮天", 7, "魔族", 32, 23, "ミヤコ", "プリンを食べること", 1, 0, "B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "悪魔偽王国軍（ディアボロス）", 130, 14);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ボクは誰よりも美しい", 100801, "大空直美", 15, "エルフ", 40, 10, "ユキ", "鏡で自分を見ること", 10, 0, "AB", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ヴァイスフリューゲル　ランドソル支部", 150, 14);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("前世を信じる中二病患者、「疾風の冥姫」", 100901, "髙野麻美", 13, "魔族", 45, 5, "アンナ", "小説執筆", 7, 0, "A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "トワイライトキャラバン", 159, 17);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("マホマホ王国のプリンセス", 101001, "内田真礼", 10, "獣人族", 42, 22, "マホ", "空想、ぬいぐるみ集め", 9, 0, "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "自警団（カォン）", 155, 16);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人懐っこくてマシンガントークな妹系少女", 101101, "阿澄佳奈", 3, "ヒューマン", 44, 25, "リノ", "お裁縫", 8, 0, "A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "ラビリンス", 156, 15);
