INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("泣き虫で臆病な守ってあげたい女の子", 102101, "植田佳奈", 9, "ヒューマン", 40, 9, "クルミ", "観劇、おままごと", 6, 0, "B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "サレンディア救護院", 150, 12);
