INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("占いが得意な霊能少女", 108101, "大坪由佳", 7, "魔族", 42, 22, "シノブ（ハロウィン）", "占い", 12, 0, "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "悪魔偽王国軍（ディアボロス）", 157, 18);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("プリン大好きゴースト娘", 108201, "雨宮天", 7, "魔族", 32, 23, "ミヤコ（ハロウィン）", "プリンを食べること", 1, 0, "B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "悪魔偽王国軍（ディアボロス）", 130, 14);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ちょっとおませな恋に恋する女の子", 108301, "久野美咲", 14, "魔族", 22, 3, "ミサキ（ハロウィン）", "ファッション誌鑑賞、コスメ集め", 1, 0, "A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ルーセント学院", 120, 11);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人々を守るために歌う、唱喚士の少女", 108401, "福原綾香", 4, "ヒューマン", 46, 3, "チカ（クリスマス）", "各種楽器", 6, 0, "O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "カルミナ", 163, 17);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("泣き虫で臆病な守ってあげたい女の子", 108501, "植田佳奈", 9, "ヒューマン", 40, 9, "クルミ（クリスマス）", "観劇、おままごと", 6, 0, "B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "サレンディア救護院", 150, 12);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ぷうきちといつも一緒！", 108601, "芹澤優", 9, "ヒューマン", 38, 10, "アヤネ（クリスマス）", "屋内でできる遊び", 5, 0, "B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "サレンディア救護院", 148, 14);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人助けが大好き！　前向き格闘娘", 108701, "東山奈央", 2, "獣人族", 44, 27, "ヒヨリ（ニューイヤー）", "人助け、応援", 8, 0, "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "トゥインクルウィッシュ", 155, 16);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("戦闘のサポートが得意な、心優しい少女", 108801, "種田梨沙", 2, "ヒューマン", 47, 5, "ユイ（ニューイヤー）", "料理、人間観察", 4, 0, "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "トゥインクルウィッシュ", 158, 17);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("クールで何事にも真っ直ぐな剣士", 108901, "早見沙織", 2, "魔族", 46, 12, "レイ（ニューイヤー）", "読書、乗馬、お茶", 1, 0, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "トゥインクルウィッシュ", 163, 18);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("運命の相手に一途すぎる乙女", 109001, "橋本ちなみ", 13, "魔族", 43, 30, "エリコ（バレンタイン）", "実験、裁縫、料理", 7, 0, "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "トワイライトキャラバン", 154, 16);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("お姉ちゃんがお世話してあげるからねっ！", 109101, "生天目仁美", 3, "ヒューマン", 54, 24, "シズル（バレンタイン）", "家事全般", 10, 0, "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "ラビリンス", 168, 18);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("英霊と契約を結んだマナリアの天才王女", 109201, "日笠陽子", "", "ヒューマン", 55, 1, "アン", "読書", 12, 0, "AB", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "？？？", 156, 17);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("マナリア魔法学院の新入生", 109301, "こやまきみこ", "", "ヒューマン", 45, 4, "ルゥ", "食べること、眠ること", 2, 0, "O", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "？？？", 144, 16);
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人を超越した力を有す心優しい竜姫", 109401, "福原綾香", "", "半人半竜", 67, 3, "グレア", "ピアノ", 11, 0, "B", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "？？？", 167, 17);
